INSERT INTO `page_contents` VALUES (1,'home','Accueil','{\"hero\": {\"body\": \"ALSAR est un parti politique sénégalais porté par une troisième voie pragmatique — entre opposition et pouvoir en place, tournée vers des résultats concrets pour le Sénégal.\", \"kicker\": \"Alliance pour la Synergie des Actions Républicaines (ALSAR)\", \"slides\": [{\"image\": {\"alt\": \"ALSAR sur le terrain à Podor (photo 1)\", \"path\": \"pages/home/hero/slides/0/slider-img-1.webp\"}}, {\"image\": {\"alt\": \"ALSAR sur le terrain à Podor (photo 2)\", \"path\": \"pages/home/hero/slides/1/slider-img-2.webp\"}}, {\"image\": {\"alt\": \"ALSAR sur le terrain à Podor (photo 3)\", \"path\": \"pages/home/hero/slides/2/slider-img-3.webp\"}}, {\"image\": {\"alt\": \"ALSAR sur le terrain à Podor (photo 4)\", \"path\": \"pages/home/hero/slides/3/slider-img-4.webp\"}}, {\"image\": {\"alt\": \"ALSAR sur le terrain à Podor (photo 5)\", \"path\": \"pages/home/hero/slides/4/slider-img-5.webp\"}}], \"headline\": \"La Force du Changement, l\'énergie du Progrès.\", \"cta_primary_label\": \"Rejoindre ALSAR\", \"cta_secondary_label\": \"Découvrir le programme\"}, \"join_cta\": {\"body\": \"Devenez adhérent, bénévole ou relais local. Adhésion en ligne, cotisation et carte de membre numérique incluses.\", \"title\": \"Le travail et la racine — ensemble, pour le Sénégal.\", \"kicker\": \"Rejoignez-nous\", \"photos\": [{\"image\": {\"alt\": \"ALSAR sur le terrain (photo 2)\", \"path\": \"pages/home/join_cta/photos/0/slider-img-2.webp\"}}, {\"image\": {\"alt\": \"ALSAR sur le terrain (photo 3)\", \"path\": \"pages/home/join_cta/photos/1/slider-img-3.webp\"}}, {\"image\": {\"alt\": \"ALSAR sur le terrain (photo 4)\", \"path\": \"pages/home/join_cta/photos/2/slider-img-4.webp\"}}, {\"image\": {\"alt\": \"ALSAR sur le terrain (photo 5)\", \"path\": \"pages/home/join_cta/photos/3/slider-img-5.webp\"}}], \"cta_label\": \"Rejoindre ALSAR\"}, \"brand_ticker\": {\"phrases\": [{\"text\": \"ALSAR\"}, {\"text\": \"La Force du Changement\"}, {\"text\": \"L\'Énergie du Progrès\"}, {\"text\": \"Travail & Mérite\"}, {\"text\": \"Solidarité\"}, {\"text\": \"Bonne Gouvernance\"}]}, \"impact_stats\": {\"intro\": \"De la mairie de Podor à la scène nationale, ALSAR avance par des actes vérifiables plutôt que par des slogans.\", \"stats\": [{\"mode\": \"count_up_year\", \"label\": \"ans à la tête de la mairie de Podor, élu en janvier 2022.\", \"value\": \"2022\"}, {\"mode\": \"count_up_number\", \"label\": \"axes structurent le programme national, de l\'emploi à la gouvernance.\", \"value\": \"6\"}, {\"mode\": \"static\", \"label\": \"reconnaissance officielle d\'ALSAR (Alliance pour la Synergie des Actions Républicaines) comme parti politique, après plus d\'une décennie de terrain depuis ALPAR (2014).\", \"value\": \"2026\"}], \"title\": \"Des engagements tenus, une trajectoire claire.\", \"video\": {\"alt\": \"ALSAR sur le terrain — mobilisation et action à Podor\", \"path\": \"pages/home/impact_stats/video/videoHero.mp4\"}, \"kicker\": \"Bilan & trajectoire\"}, \"regions_teaser\": {\"body\": \"ALSAR est présent dans les 14 régions du Sénégal. Les coordinations locales, à l\'image d\'ALSAR Sagatta, seront détaillées au fur et à mesure de leur structuration officielle.\", \"title\": \"14 régions, une seule ambition nationale.\", \"kicker\": \"Régions\", \"map_caption\": \"Dakar — siège officiel du parti (en or sur la carte)\"}, \"program_pillars\": {\"title\": \"Trois axes, parmi six, pour transformer le Sénégal.\", \"kicker\": \"Le programme\", \"pillars\": [{\"id\": \"emploi\", \"icon\": \"Briefcase\", \"text\": \"Création d\'emplois, soutien à l\'entrepreneuriat et allégement fiscal sur les produits de première nécessité.\", \"image\": {\"alt\": \"\", \"path\": \"pages/home/program_pillars/pillars/0/slider-img-2.webp\"}, \"title\": \"Pouvoir d\'achat et emploi\"}, {\"id\": \"alimentaire\", \"icon\": \"Wheat\", \"text\": \"Modernisation du secteur agropastoral et protection des droits des agriculteurs et éleveurs.\", \"image\": {\"alt\": \"\", \"path\": \"pages/home/program_pillars/pillars/1/slider-img-3.webp\"}, \"title\": \"Souveraineté alimentaire\"}, {\"id\": \"gouvernance\", \"icon\": \"ShieldCheck\", \"text\": \"Mécanismes de contrôle et de transparence dans la gestion des ressources publiques.\", \"image\": {\"alt\": \"\", \"path\": \"pages/home/program_pillars/pillars/2/slider-img-5.webp\"}, \"title\": \"Transparence et bonne gouvernance\"}], \"cta_label\": \"Voir les 6 axes du programme\"}, \"president_teaser\": {\"body\": \"Originaire de Soueïma (Podor), Mamadou Racine Sy dirige la commune de Podor depuis janvier 2022 après un parcours d\'entrepreneur hôtelier. Fondateur en 2014 du mouvement ALPAR à l\'origine d\'ALSAR, il porte aujourd\'hui une troisième voie pragmatique pour le Sénégal.\", \"quote\": \"Un homme d\'action, entre réussite entrepreneuriale, mandat municipal et engagement national.\", \"badges\": [{\"text\": \"Maire de Podor depuis 2022\"}, {\"text\": \"Fondateur d\'ALPAR (2014)\"}, {\"text\": \"Ancien PDG, King Fahd Palace\"}], \"kicker\": \"Le Président\", \"portrait\": {\"alt\": \"Mamadou Racine Sy, Président d\'ALSAR\", \"path\": \"pages/home/president_teaser/portrait/Photo-du-président-racine-sy-1.jpeg\"}, \"cta_label\": \"Découvrir son parcours\"}}',NULL,NULL,'2026-08-09 23:10:19','2026-08-10 00:04:20'),(2,'le-parti','Le Parti','{\"header\": {\"image\": {\"alt\": \"ALSAR sur le terrain\", \"path\": \"pages/le-parti/header/image/slider-img-2.webp\"}, \"intro\": \"D\'un mouvement citoyen né à Podor à un parti politique national : notre positionnement, nos valeurs et la manière dont nous nous organisons.\", \"title\": \"Vision, histoire et organisation d\'ALSAR\", \"kicker\": \"Le Parti\"}, \"vision\": {\"title\": \"Un Sénégal prospère, équitable et solidaire.\", \"kicker\": \"Vision\", \"values\": [{\"text\": \"Le travail comme socle du progrès individuel et collectif.\", \"label\": \"Travail (Liggey) et mérite\"}, {\"text\": \"Personne ne doit être laissé pour compte.\", \"label\": \"Solidarité et justice sociale\"}, {\"text\": \"Rendre compte de l\'usage des ressources publiques.\", \"label\": \"Bonne gouvernance et transparence\"}, {\"text\": \"Des résultats concrets plutôt que des postures.\", \"label\": \"Pragmatisme et efficacité\"}, {\"text\": \"Rassembler au-delà de l\'opposition et du pouvoir.\", \"label\": \"Unité nationale au-delà des clivages partisans\"}], \"body_intro\": \"Construit par un développement inclusif et durable, en dehors des clivages classiques opposition/pouvoir.\", \"body_detail\": \"ALSAR se définit comme une <strong>troisième voie</strong> : un pragmatisme orienté résultats plutôt qu\'une ligne idéologique classique.\"}, \"statuts\": {\"title\": \"Statuts officiels et rapports d\'activité\", \"kicker\": \"Statuts & Transparence\", \"coming_soon_text\": \"Les statuts officiels du parti et les rapports d\'activité seront publiés ici dès leur validation. C\'est un engagement de transparence, pas un simple espace à remplir.\"}, \"histoire\": {\"image\": {\"alt\": \"ALSAR — illustration de l\'histoire du parti\", \"path\": \"pages/le-parti/histoire/image/slider-img-1.webp\"}, \"title\": \"Notre histoire\", \"chronology\": [{\"date\": \"Avant 2014\", \"text\": \"Mamadou Racine Sy se fait connaître comme entrepreneur hôtelier (PDG du King Fahd Palace) et figure du patronat touristique sénégalais.\"}, {\"date\": \"2014\", \"text\": \"Convaincu que le développement doit partir des territoires, Mamadou Racine Sy crée ALPAR (And Liggey Podor ak Racine), mouvement citoyen destiné à accompagner les initiatives de développement dans le département de Podor.\"}, {\"date\": \"2019\", \"text\": \"Face à l\'adhésion grandissante des populations, ALPAR évolue pour devenir ALSAR (And Liggey Sénégal ak Racine), mouvement national porté par le travail, la solidarité, l\'investissement productif et la bonne gouvernance.\"}, {\"date\": \"Janvier 2022\", \"text\": \"Élection de Mamadou Racine Sy à la mairie de Podor.\"}, {\"date\": \"2024\", \"text\": \"Le mouvement ALSAR participe pour la première fois à une élection nationale, en présentant une liste indépendante aux élections législatives — nouvelle étape de son implantation politique.\"}, {\"date\": \"2026\", \"text\": \"Après plus d\'une décennie d\'implantation progressive commencée avec ALPAR, ALSAR obtient sa reconnaissance officielle comme parti politique sous l\'appellation Alliance pour la Synergie des Actions Républicaines (ALSAR), consacrant un travail de terrain engagé depuis 2014 et ouvrant une nouvelle phase de structuration nationale.\"}]}, \"organisation\": {\"note\": \"Les mouvements des jeunes et des femmes ainsi que les coordinations régionales/départementales sont en cours de structuration officielle. Cette page sera complétée au fur et à mesure de leur mise en place.\", \"facts\": [{\"label\": \"Présidence du parti\", \"value\": \"Mamadou Racine Sy\"}, {\"label\": \"Coordination locale identifiée\", \"value\": \"ALSAR Sagatta — Ndeye Sarr Diop\"}], \"title\": \"Une structuration en cours\", \"kicker\": \"Organisation\"}}',NULL,NULL,'2026-08-09 23:10:19','2026-08-09 23:11:33'),(3,'le-president','Le Président','{\"header\": {\"image\": {\"alt\": \"Mamadou Racine Sy sur le terrain\", \"path\": \"pages/le-president/header/image/slider-img-4.webp\"}, \"intro\": \"Entrepreneur, maire de Podor depuis janvier 2022, fondateur en 2014 du mouvement ALPAR à l\'origine d\'ALSAR — un parcours entre réussite entrepreneuriale et engagement public.\", \"title\": \"Mamadou Racine Sy\", \"kicker\": \"Le Président\"}, \"discours\": {\"title\": \"Sa parole, relayée par la presse sénégalaise\", \"kicker\": \"Discours & Revue de presse\", \"press_outlets\": [{\"text\": \"Dakaractu\"}, {\"text\": \"La Vie Sénégalaise\"}, {\"text\": \"SansLimiteSn\"}], \"coming_soon_text\": \"Aucun discours filmé n\'est pour l\'instant documenté publiquement. Cette section sera alimentée au fur et à mesure des interventions du Président.\"}, \"parcours\": {\"image\": {\"alt\": \"ALSAR — illustration du parcours du Président\", \"path\": \"pages/le-president/parcours/image/Photo-président-racine-sy-2.jpeg\"}, \"title\": \"Parcours\", \"career\": [{\"date\": \"Années 1980\", \"text\": \"Débuts dans le secteur privé sénégalais et l\'hôtellerie, au sein du groupe hôtelier familial.\"}, {\"date\": \"Années 1990\", \"text\": \"Développement des activités hôtelières du Groupe Sy, qui devient un acteur majeur du tourisme sénégalais.\"}, {\"date\": \"Années 2000\", \"text\": \"Direction du King Fahd Palace : renforce le groupe hôtelier et œuvre au rayonnement international de la destination Sénégal, à la création d\'emplois et à l\'investissement touristique.\"}, {\"date\": \"Années 2000-2020\", \"text\": \"Accède aux principales responsabilités patronales nationales et régionales : Président de la Fédération des Organisations Patronales de l\'Industrie Touristique du Sénégal (FOPITS), Président du Conseil National du Tourisme, Président de la COPITOUR/CEDEAO, Premier Vice-Président du Conseil National du Patronat (CNP). Il siège également dans plusieurs conseils d\'administration, dont l\'IPRES, la Caisse de Sécurité Sociale, Sénégal Hôtels et Africa Global Logistics (AGL).\"}, {\"date\": \"2014\", \"text\": \"Convaincu que le développement doit partir des territoires, crée ALPAR (And Liggey Podor ak Racine), mouvement citoyen destiné à accompagner les initiatives de développement dans le département de Podor.\"}, {\"date\": \"2019\", \"text\": \"Face à l\'adhésion grandissante des populations, ALPAR évolue pour devenir ALSAR (And Liggey Sénégal ak Racine), mouvement national porté par le travail, la solidarité, l\'investissement productif et la bonne gouvernance.\"}, {\"date\": \"Janvier 2022\", \"text\": \"Élu maire de la commune de Podor — conduit depuis lors plusieurs projets structurants : assainissement, éclairage public, modernisation du marché central, voirie, aménagement urbain et actions sociales en faveur des jeunes, des femmes et des personnes vulnérables.\"}, {\"date\": \"2024\", \"text\": \"Le mouvement ALSAR participe pour la première fois à une élection nationale, en présentant une liste indépendante aux élections législatives.\"}, {\"date\": \"2026\", \"text\": \"Après plus d\'une décennie d\'implantation progressive commencée avec ALPAR, ALSAR obtient sa reconnaissance officielle comme parti politique sous l\'appellation Alliance pour la Synergie des Actions Républicaines (ALSAR) — ouvrant une nouvelle phase de structuration nationale.\"}]}, \"portrait\": {\"body\": \"Originaire de Soueïma, dans la commune de Podor (région du Fouta), Mamadou Racine Sy s\'est imposé au fil des décennies comme l\'un des principaux acteurs du tourisme, de l\'hôtellerie et du patronat au Sénégal et en Afrique de l\'Ouest, avant de mettre cette expérience au service des populations par l\'engagement public. Il siège aujourd\'hui dans plusieurs conseils d\'administration de grandes institutions, dont l\'IPRES, la Caisse de Sécurité Sociale, Sénégal Hôtels et Africa Global Logistics (AGL), et porte à la tête d\'ALSAR une troisième voie pragmatique pour le Sénégal.\", \"facts\": [{\"mode\": \"count_up_year\", \"label\": \"ans à la tête de la mairie de Podor\", \"value\": \"2022\"}, {\"mode\": \"static\", \"label\": \"mandat municipal (depuis 2022)\", \"value\": \"1\"}, {\"mode\": \"static\", \"label\": \"Vice-Président du Conseil National du Patronat\", \"value\": \"1er\"}], \"image\": {\"alt\": \"Mamadou Racine Sy, Président d\'ALSAR\", \"path\": \"pages/le-president/portrait/image/Photo-du-président-racine-sy-1.jpeg\"}, \"title\": \"Un homme d\'action, entre entreprise et service public.\", \"kicker\": \"Portrait\"}, \"realisations\": {\"body\": \"Modernisation du marché central, projets d\'assainissement, d\'éclairage public, de voirie et d\'aménagement urbain, actions sociales récurrentes (distribution de bœufs pendant le Ramadan, soutien aux étudiants) et revendication portée pour l\'érection du département de Podor en région à part entière.\", \"title\": \"Réalisations à Podor\"}}',NULL,NULL,'2026-08-09 23:10:19','2026-08-09 23:11:33'),(4,'programme','Programme','{\"axes\": {\"axes\": [{\"id\": \"emploi\", \"icon\": \"Briefcase\", \"text\": \"Création d\'emplois, soutien à l\'entrepreneuriat et modernisation des secteurs clés pour une croissance inclusive. Allégement fiscal sur les produits de première nécessité et révision de l\'impôt sur le revenu.\", \"title\": \"Pouvoir d\'achat et emploi\"}, {\"id\": \"alimentaire\", \"icon\": \"Wheat\", \"text\": \"Modernisation du secteur agropastoral, sécurité alimentaire, protection des droits des agriculteurs et éleveurs.\", \"title\": \"Souveraineté alimentaire\"}, {\"id\": \"desenclavement\", \"icon\": \"Route\", \"text\": \"Programme d\'infrastructures rurales pour connecter le pays aux opportunités de développement.\", \"title\": \"Désenclavement et développement rural\"}, {\"id\": \"foncier\", \"icon\": \"LandPlot\", \"text\": \"Garantir un accès équitable et sécurisé au foncier, question sensible pour de nombreuses collectivités locales.\", \"title\": \"Sécurisation foncière\"}, {\"id\": \"femmes\", \"icon\": \"HeartHandshake\", \"text\": \"Renforcement des droits des femmes et construction d’une société plus juste et inclusive.\", \"title\": \"Droits des femmes et politique familiale\"}, {\"id\": \"gouvernance\", \"icon\": \"ShieldCheck\", \"text\": \"Mécanismes de contrôle et de transparence dans la gestion des ressources publiques.\", \"title\": \"Transparence et bonne gouvernance\"}]}, \"intro\": {\"text\": \"Ce programme est aujourd\'hui énoncé sous forme de grands principes. Une version chiffrée, avec échéances et indicateurs de suivi, est en préparation — téléchargement du programme complet (PDF) à venir.\"}, \"header\": {\"image\": {\"alt\": \"ALSAR sur le terrain\", \"path\": \"pages/programme/header/image/slider-img-3.webp\"}, \"intro\": \"Un pragmatisme orienté résultats, structuré autour de six priorités : économie, agriculture, infrastructures, foncier, égalité et gouvernance.\", \"title\": \"Six axes pour transformer le Sénégal\", \"kicker\": \"Programme\"}}',NULL,NULL,'2026-08-09 23:10:19','2026-08-09 23:11:34'),(5,'regions','Régions','{\"map\": {\"caption\": \"Cliquez sur une région (ou naviguez au clavier) pour afficher les informations disponibles.\"}, \"header\": {\"image\": {\"alt\": \"ALSAR sur le terrain\", \"path\": \"pages/regions/header/image/slider-img-4.webp\"}, \"intro\": \"ALSAR est présent dans les 14 régions du pays — cliquez sur une région de la carte interactive pour découvrir les informations disponibles sur sa coordination locale.\", \"title\": \"Une présence nationale, région par région\", \"kicker\": \"Régions\"}, \"region_info\": {\"regions\": [{\"note\": \"Siège officiel du parti — Cité Keur Gorgui, immeuble Hermès 2, Dakar.\", \"contact\": \"\", \"section\": \"Siège national\", \"region_name\": \"Dakar\"}, {\"note\": \"Coordination locale à Podor, berceau historique du mouvement (ALPAR, 2014), identifiée publiquement.\", \"contact\": \"Ndeye Sarr Diop\", \"section\": \"ALSAR Sagatta\", \"region_name\": \"Saint-Louis\"}]}, \"default_note\": {\"text\": \"ALSAR est présent dans cette région. Le nom et les contacts de sa coordination locale ne sont pas encore publiés — cette page sera mise à jour au fur et à mesure de leur communication officielle.\"}, \"sections_locales\": {\"title\": \"Présent dans les 14 régions, coordination détaillée au fur et à mesure\", \"kicker\": \"Sections locales\"}}',NULL,NULL,'2026-08-09 23:10:19','2026-08-09 23:11:34'),(6,'mediatheque','Médiathèque','{\"video\": {\"body\": \"Un aperçu du terrain et de la mobilisation militante d\'ALSAR.\", \"title\": \"ALSAR en mouvement\", \"kicker\": \"Vidéo\"}, \"header\": {\"image\": {\"alt\": \"ALSAR sur le terrain\", \"path\": \"pages/mediatheque/header/image/slider-img-5.webp\"}, \"intro\": \"La vie du parti en images — galerie photo, vidéo et espace presse téléchargeable.\", \"title\": \"Photos, vidéos et ressources presse\", \"kicker\": \"Médiathèque\"}, \"presse\": {\"body\": \"Le dossier de presse complet (photos HD, biographie courte, communiqués) est en préparation. Le logo du parti est d\'ores et déjà disponible au téléchargement.\", \"title\": \"Kit média\", \"kicker\": \"Espace presse\"}, \"gallery\": {\"intro\": \"Cliquez sur une photo pour l\'agrandir.\", \"title\": \"Photos\", \"kicker\": \"Galerie\", \"photos\": [{\"image\": {\"alt\": \"ALSAR sur le terrain à Podor (photo 1)\", \"path\": \"pages/mediatheque/gallery/photos/0/slider-img-1.webp\"}, \"caption\": \"\"}, {\"image\": {\"alt\": \"ALSAR sur le terrain à Podor (photo 2)\", \"path\": \"pages/mediatheque/gallery/photos/1/slider-img-2.webp\"}, \"caption\": \"\"}, {\"image\": {\"alt\": \"ALSAR sur le terrain à Podor (photo 3)\", \"path\": \"pages/mediatheque/gallery/photos/2/slider-img-3.webp\"}, \"caption\": \"\"}, {\"image\": {\"alt\": \"ALSAR sur le terrain à Podor (photo 4)\", \"path\": \"pages/mediatheque/gallery/photos/3/slider-img-4.webp\"}, \"caption\": \"\"}, {\"image\": {\"alt\": \"ALSAR sur le terrain à Podor (photo 5)\", \"path\": \"pages/mediatheque/gallery/photos/4/slider-img-5.webp\"}, \"caption\": \"\"}, {\"image\": {\"alt\": \"ALSAR — photo d\'archive\", \"path\": \"pages/mediatheque/gallery/photos/5/imgi_67_.webp\"}, \"caption\": \"\"}, {\"image\": {\"alt\": \"Mamadou Racine Sy, Président d\'ALSAR\", \"path\": \"pages/mediatheque/gallery/photos/6/photo-de-racine-sy.webp\"}, \"caption\": \"Mamadou Racine Sy, Président d\'ALSAR\"}]}, \"podcasts\": {\"title\": \"Bientôt disponible\", \"kicker\": \"Podcasts & interviews\", \"coming_soon_text\": \"Aucune interview ou podcast n\'est aujourd\'hui documenté publiquement. Cette section sera alimentée au fur et à mesure des prises de parole du parti.\"}}',NULL,NULL,'2026-08-09 23:10:20','2026-08-09 23:11:34'),(7,'site-settings','En-tête & pied de page','{\"footer\": {\"logo\": {\"alt\": \"\", \"path\": \"pages/site-settings/footer/logo/logo-alsar.png\"}, \"tagline\": \"Alliance pour la Synergie des Actions Républicaines — Cité Keur Gorgui, Dakar.\", \"brand_text\": \"ALSAR\", \"facebook_url\": \"\", \"contact_email\": \"contact@alsar.sn\", \"copyright_text\": \"ALSAR. Tous droits réservés.\", \"contact_address\": \"Cité Keur Gorgui, immeuble Hermès 2, Dakar\"}, \"header\": {\"logo\": {\"alt\": \"\", \"path\": \"pages/site-settings/header/logo/logo-alsar.png\"}, \"cta_label\": \"Adhérer\", \"nav_items\": [{\"label\": \"Le Parti\"}, {\"label\": \"Le Président\"}, {\"label\": \"Programme\"}, {\"label\": \"Actualités\"}, {\"label\": \"Médiathèque\"}, {\"label\": \"Régions\"}], \"brand_text\": \"ALSAR\"}}',NULL,NULL,'2026-08-09 23:10:20','2026-08-09 23:11:34');
